function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const IDS = ['D04170','D03610','D03395','D03503','D03558','D03859','D03662','D03469','D03671','D04221','D03312','D04044','D03477','D04113','D04155','D03860','D03711','D03956','D04224','D03925','D04168','D04074','D04178','D03868','D04129','D03457','D03906','D03366','D03297','D04096','D03425','D03650'];
const want = new Set(IDS);
const pipe = $input.all().map(function (i) { return i.json; });
const idCount = {}; for (const p of pipe) { const id = s(p.deal_id); if (id) { idCount[id] = (idCount[id] || 0) + 1; } }
const dupIds = Object.keys(idCount).filter(function (k) { return idCount[k] > 1; });
const rows = pipe.filter(function (p) { return want.has(s(p.deal_id)); }).map(function (p) {
  return { row: p.row_number, deal_id: s(p.deal_id), startup: s(p.startup), investor: s(p.investor), email: s(p.email), deal_shared: s(p.deal_shared), pause: s(p.pause), next_action: s(p.next_action), next_due: s(p.next_due), match_type: s(p.match_type), notes_tail: s(p.notes).slice(-110) }; });
// same startup|investor pair appearing more than once among these
const pairCount = {}; for (const p of pipe) { const k = nz(p.startup) + '|' + nz(p.investor); pairCount[k] = (pairCount[k] || 0) + 1; }
for (const r of rows) { r.pair_rows_in_pipeline = pairCount[nz(r.startup) + '|' + nz(r.investor)] || 0; r.id_rows_in_pipeline = idCount[r.deal_id]; }
return [{ json: { pipeline_rows: pipe.length, duplicated_deal_ids_total: dupIds.length, flagged_ids_found_rows: rows.length, rows: rows } }];
